const recordGold = `-- name: RecordGold :exec
INSERT INTO app.gold_ledger (player_id, delta, balance_after, reason, ref_id)
VALUES ($1, $2, $3, $4, $5)
`

type RecordGoldParams struct {
	PlayerID     uuid.UUID
	Delta        int64
	BalanceAfter int64
	Reason       string
	RefID        *string
}

func (q *Queries) RecordGold(ctx context.Context, arg RecordGoldParams) error {
	_, err := q.db.Exec(ctx, recordGold,
		arg.PlayerID,
		arg.Delta,
		arg.BalanceAfter,
		arg.Reason,
		arg.RefID,
	)
	return err
}

